  };
  const observe = () => {
    if (clarification.current.pending !== intent) return;
    const next = clarification.current.origin === intent.origin ? readClarification() : null;
    if (!next || next.task.needsClarification !== clarificationValue || !next.entry.fullToken) {
      intent.cancel();
